static void test_der_encode(void) {
    TEST_SUITE("p256_ecdsa_der_sig_encode — matches cryptography's DER encoding");
    for (int i = 0; i < NDER; i++) {
        uint8_t out[72];
        int64_t len = p256_ecdsa_der_sig_encode(out, DERS[i].r, DERS[i].s);
        ASSERT_EQ("length matches", DERS[i].der_len, (int)len);
        ASSERT_EQ("bytes match", 0, memcmp(out, DERS[i].der, (unsigned long)DERS[i].der_len));
    }
}

int main(void) {
    test_der_encode();
    test_summary();
    return 0;
}
